console.log("[Expression Lock] Service worker started.");chrome.runtime.onInstalled.addListener(()=>{console.log("Extension installed.")});chrome.alarms.create("demo-trigger",{delayInMinutes:.1});chrome.alarms.onAlarm.addListener(e=>{e.name==="demo-trigger"&&chrome.tabs.query({url:"*://meet.google.com/*"},o=>{o.forEach(r=>{chrome.tabs.sendMessage(r.id,{type:"TRIGGER_VERIFICATION",nonce:"mock-nonce-12345"})})})});chrome.runtime.onMessage.addListener((e,o,r)=>{e.type==="VERIFICATION_COMPLETE"&&console.log("[Background] Received verified signed result:",e.payload)});
